};

UserEmail.getConfirmation = async function (uid) {
	const code = await db.get(`confirm:byUid:${uid}`);
	if (!code) {
		return null;
	}
	const confirmation = await db.getObject(`confirm:${code}`);
	return confirmation && parseInt(confirmation.uid, 10) === parseInt(uid, 10) ? confirmation : null;
};

UserEmail.getEmailForValidation = async function (uid) {
	const email = await user.getUserField(uid, 'email');
	if (email) {
		return email;
	}
	const confirmation = await UserEmail.getConfirmation(uid);
	return confirmation && confirmation.email;
};

UserEmail.isValidationPending = async function (uid, email) {
	const confirmation = await UserEmail.getConfirmation(uid);
	return !!(confirmation && confirmation.email &&
		(!email || confirmation.email.toLowerCase() === email.toLowerCase()) &&
		Number(confirmation.expires) > Date.now());
};

UserEmail.expireValidation = async function (uid) {
	const code = await db.get(`confirm:byUid:${uid}`);
	await db.deleteAll([`confirm:byUid:${uid}`, ...(code ? [`confirm:${code}`] : [])]);
};

